'use strict';

var OPTS = [
	{
		'rules': {
			'semi': 'error',
			'eqeqeq': 'error'
		}
	}
];
var valid = [];

// Clean example with proper style:
var test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @example',
		'* var y = square( 3.0 );',
		'* // returns 9.0',
		'*/',
		'function square( x ) {',
		'\treturn x * x;',
		'}'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// JSDoc without @example tag:
test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @param {number} x - input value',
		'* @returns {number} squared value',
		'*/',
		'function square( x ) {',
		'\treturn x * x;',
		'}'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// Multiple clean examples:
test = {
	'code': [
		'/**',
		'* Computes an absolute value.',
		'*',
		'* @example',
		'* var v = abs( -1.0 );',
		'* // returns 1.0',
		'*',
		'* @example',
		'* var v = abs( 2.0 );',
		'* // returns 2.0',
		'*/',
		'function abs( x ) {',
		'\tif ( x < 0 ) {',
		'\t\treturn -x;',
		'\t}',
		'\treturn x;',
		'}'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// Example with require statement:
test = {
	'code': [
		'/**',
		'* Computes an absolute value.',
		'*',
		'* @module @stdlib/math/base/special/abs',
		'*',
		'* @example',
		'* var abs = require( \'@stdlib/math/base/special/abs\' );',
		'*',
		'* var v = abs( -1.0 );',
		'* // returns 1.0',
		'*/',
		'var main = require( \'./main.js\' );',
		'',
		'module.exports = main;'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// Example with console.log:
test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @example',
		'* var y = square( 3.0 );',
		'* console.log( y );',
		'*/',
		'function square( x ) {',
		'\treturn x * x;',
		'}'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// Variable declaration with example:
test = {
	'code': [
		'/**',
		'* Maximum value.',
		'*',
		'* @example',
		'* var v = MAX;',
		'* // returns 100',
		'*/',
		'var MAX = 100;'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// Example with multiple statements across lines:
test = {
	'code': [
		'/**',
		'* Checks if positive.',
		'*',
		'* @example',
		'* var bool = isPositive( 3.0 );',
		'* // returns true',
		'*',
		'* bool = isPositive( -1.0 );',
		'* // returns false',
		'*/',
		'function isPositive( x ) {',
		'\treturn x > 0;',
		'}'
	].join( '\n' ),
	'options': OPTS
};
valid.push( test );

// No options provided (rule does nothing):
test = {
	'code': [
		'/**',
		'* Squares a number.',
		'*',
		'* @example',
		'* var y = square( 3.0 )',
		'*/',
		'function square( x ) {',
		'\treturn x * x;',
		'}'
	].join( '\n' )
};
valid.push( test );


// EXPORTS //

module.exports = valid;
